	}

	// build dsn
	dsn := host
	if port != "" {
		dsn += ":" + port
	}

	// build user/pass
	if u.User != nil {
		if un := u.User.Username(); len(un) > 0 {
			if up, ok := u.User.Password(); ok {
				un += "/" + up
			}
			dsn = un + "@//" + dsn
		}
	}

	if service != "" {
		dsn += "/" + service
	}
	if instance != "" {
		dsn += "/" + instance
	}

	return dsn, nil
}

