func redactDatabaseURL(raw string) string {
	parsed, err := url.Parse(raw)
	if err != nil {
		return "[redacted]"
	}
	if parsed.User != nil {
		if _, ok := parsed.User.Password(); ok {
			parsed.User = url.UserPassword(parsed.User.Username(), "[redacted]")
		}
	}
	query := parsed.Query()
	for key := range query {
		switch strings.ToLower(key) {
		case "password", "pass", "pwd":
			query.Set(key, "[redacted]")
		}
	}
	parsed.RawQuery = query.Encode()
	return parsed.String()
}

// DatabaseProtocol identifies a supported database engine.
type DatabaseProtocol uint8

const (
	DatabaseProtocolUnknown DatabaseProtocol = iota
	DatabaseProtocolSQLite
	DatabaseProtocolPostgres
	DatabaseProtocolMySQL
)

// Short aliases make protocol values convenient to use in configuration code.
const (
	SQLite   = DatabaseProtocolSQLite
	Postgres = DatabaseProtocolPostgres
	MySQL    = DatabaseProtocolMySQL
)

var databaseProtocols = map[DatabaseProtocol]string{
	DatabaseProtocolSQLite:   "sqlite",
	DatabaseProtocolPostgres: "postgres",
	DatabaseProtocolMySQL:    "mysql",
}

func (p DatabaseProtocol) String() string {
	if value, ok := databaseProtocols[p]; ok {
		return value
	}
	return "unknown"
}

// DefaultPort returns the standard TCP port for a protocol, or zero when the
// protocol does not use a TCP port.
func (p DatabaseProtocol) DefaultPort() int {
	switch p {
	case DatabaseProtocolPostgres:
		return 5432
	case DatabaseProtocolMySQL:
		return 3306
	default:
		return 0
	}
}

// ParseDatabaseProtocol parses a database protocol setting.
func ParseDatabaseProtocol(value string) (DatabaseProtocol, error) {
	switch strings.ToLower(strings.TrimSpace(value)) {
	case "sqlite":
		return DatabaseProtocolSQLite, nil
	case "postgres":
		return DatabaseProtocolPostgres, nil
	case "mysql":
		return DatabaseProtocolMySQL, nil
	default:
		return DatabaseProtocolUnknown, fmt.Errorf("db.protocol has invalid value %q; expected one of sqlite, postgres, mysql", value)
	}
}

// Validate checks the database settings. A configured URL takes precedence
// over the discrete connection fields.
func (d DatabaseConfig) Validate() error {
	if d.URL != "" {
		return nil
	}

	switch d.Protocol {
	case DatabaseProtocolSQLite:
		if strings.TrimSpace(d.Path) == "" {
			return errors.New("db.path is required when db.protocol is sqlite")
		}
	case DatabaseProtocolPostgres, DatabaseProtocolMySQL:
		if strings.TrimSpace(d.Host) == "" {
			return errors.New("db.host is required when db.url is not set")
		}
		if strings.TrimSpace(d.Name) == "" {
			return errors.New("db.name is required when db.url is not set")
		}
	default:
		if d.Protocol == DatabaseProtocolUnknown {
			return errors.New("db.protocol is required when db.url is not set")
		}
		return fmt.Errorf("db.protocol has invalid value %d; expected one of sqlite, postgres, mysql", d.Protocol)
	}

	if d.Port < 0 || d.Port > 65535 {
		return fmt.Errorf("db.port must be between 1 and 65535 when set; got %d", d.Port)
	}

	return nil
}

func (d DatabaseConfig) configured() bool {
	return d.URL != "" || d.Protocol != DatabaseProtocolUnknown || d.Host != "" || d.Port != 0 || d.User != "" || d.Password != "" || d.Name != "" || d.Path != ""
}

