// Open opens a connection to the db given a URL
func Open(cfg config.Config) (*sql.DB, Driver, error) {
	return openDatabase(cfg.Database, false)
}

func openDatabase(databaseConfig config.DatabaseConfig, migrate bool) (*sql.DB, Driver, error) {
	if err := databaseConfig.Validate(); err != nil {
		return nil, 0, err
	}

	target := databaseConfig.URL
	if target == "" {
		var err error
		target, err = databaseURL(databaseConfig)
		if err != nil {
			return nil, 0, err
		}
	}

	db, driver, err := open(target, migrate)
	if err != nil {
		return nil, 0, redactDatabaseError(err, databaseConfig)
	}

	configurePool(db, databaseConfig)
	registerMetrics(driver, db)

	return db, driver, nil
}

func configurePool(db *sql.DB, databaseConfig config.DatabaseConfig) {
	db.SetMaxIdleConns(databaseConfig.MaxIdleConn)

	if databaseConfig.MaxOpenConn > 0 {
		db.SetMaxOpenConns(databaseConfig.MaxOpenConn)
	}
	if databaseConfig.ConnMaxLifetime > 0 {
		db.SetConnMaxLifetime(databaseConfig.ConnMaxLifetime)
	}
}

func databaseURL(databaseConfig config.DatabaseConfig) (string, error) {
	if databaseConfig.URL != "" {
		return databaseConfig.URL, nil
	}
	if err := databaseConfig.Validate(); err != nil {
		return "", err
	}

	switch databaseConfig.Protocol {
	case config.DatabaseProtocolSQLite:
		if strings.HasPrefix(databaseConfig.Path, "file:") {
			return databaseConfig.Path, nil
		}
		return "file:" + databaseConfig.Path, nil
	case config.DatabaseProtocolPostgres, config.DatabaseProtocolMySQL:
		port := databaseConfig.Port
		if port == 0 {
			port = databaseConfig.Protocol.DefaultPort()
		}
		host := strings.Trim(databaseConfig.Host, "[]")
		target := stdurl.URL{
			Scheme: databaseConfig.Protocol.String(),
			Host:   net.JoinHostPort(host, strconv.Itoa(port)),
			Path:   "/" + databaseConfig.Name,
		}
		if databaseConfig.User != "" || databaseConfig.Password != "" {
			if databaseConfig.Password != "" {
				target.User = stdurl.UserPassword(databaseConfig.User, databaseConfig.Password)
			} else {
				target.User = stdurl.User(databaseConfig.User)
			}
		}
		return target.String(), nil
	default:
		return "", fmt.Errorf("db.protocol has invalid value %d; expected one of sqlite, postgres, mysql", databaseConfig.Protocol)
	}
}

func open(rawurl string, migrate bool) (*sql.DB, Driver, error) {
	d, url, err := parse(rawurl, migrate)
	if err != nil {
		return nil, 0, err
	}

	driverName := fmt.Sprintf("instrumented-%s", d)

	var dr driver.Driver

	switch d {
	case SQLite:
		dr = &sqlite3.SQLiteDriver{}
	case Postgres:
		dr = &pq.Driver{}
	case MySQL:
		dr = &mysql.MySQLDriver{}
	}

	registered := false

	for _, dd := range sql.Drivers() {
		if dd == driverName {
			registered = true
			break
		}
	}

	if !registered {
		sql.Register(driverName, instrumentedsql.WrapDriver(dr, instrumentedsql.WithTracer(opentracing.NewTracer(false))))
	}

	db, err := sql.Open(driverName, url.DSN)
	if err != nil {
		return nil, 0, fmt.Errorf("opening db for driver %s: %s", d, redactURLText(err.Error(), rawurl))
	}

	return db, d, nil
}

var (
	driverToString = map[Driver]string{
		SQLite:   "sqlite3",
		Postgres: "postgres",
		MySQL:    "mysql",
	}

	stringToDriver = map[string]Driver{
		"sqlite3":  SQLite,
		"postgres": Postgres,
		"mysql":    MySQL,
	}
)

// Driver represents a database driver
type Driver uint8

func (d Driver) String() string {
	return driverToString[d]
}

const (
	_ Driver = iota
	// SQLite ...
	SQLite
	// Postgres ...
	Postgres
	// MySQL ...
	MySQL
)

func parse(rawurl string, migrate bool) (Driver, *dburl.URL, error) {
	errURL := func(rawurl string, _ error) error {
		return fmt.Errorf("error parsing db.url %q: invalid database URL", redactedURL(rawurl))
	}

	url, err := dburl.Parse(rawurl)
	if err != nil {
		if scheme, unsupported := unsupportedDatabaseScheme(rawurl); unsupported {
			return 0, nil, fmt.Errorf("db.url has unsupported protocol %q; expected one of sqlite, postgres, mysql", scheme)
		}
		return 0, nil, errURL(rawurl, err)
	}

	driver := stringToDriver[url.Driver]
	if driver == 0 {
		return 0, nil, fmt.Errorf("unsupported database protocol %q in db.url; expected one of sqlite, postgres, mysql", url.Driver)
	}

	switch driver {
	case MySQL:
		v := url.Query()
		v.Set("multiStatements", "true")
		v.Set("parseTime", "true")
		if !migrate {
			v.Set("sql_mode", "ANSI")
		}
		url.RawQuery = v.Encode()
		// we need to re-parse since we modified the query params
		url, err = dburl.Parse(url.URL.String())

	case SQLite:
		v := url.Query()
		v.Set("cache", "shared")
		v.Set("_fk", "true")
		url.RawQuery = v.Encode()

		// we need to re-parse since we modified the query params
		url, err = dburl.Parse(url.URL.String())
	}

	if err != nil {
		return 0, nil, errURL(rawurl, err)
	}

	return driver, url, nil
}

func unsupportedDatabaseScheme(raw string) (string, bool) {
	parsed, err := stdurl.Parse(raw)
	if err != nil || parsed.Scheme == "" {
		return "", false
	}
	if driver, _ := dburl.SchemeDriverAndAliases(parsed.Scheme); driver != "" {
		return "", false
	}
	return parsed.Scheme, true
}

func redactedURL(raw string) string {
	parsed, err := stdurl.Parse(raw)
	if err != nil {
		return "[redacted]"
	}
	if parsed.User != nil {
		username := parsed.User.Username()
		if _, ok := parsed.User.Password(); ok {
			parsed.User = stdurl.UserPassword(username, "[redacted]")
		}
	}
	query := parsed.Query()
	for key := range query {
		if isSecretKey(key) {
			query.Set(key, "[redacted]")
		}
	}
	parsed.RawQuery = query.Encode()
	return parsed.String()
}

func redactURLText(message, raw string) string {
	if raw == "" {
		return message
	}
	message = strings.ReplaceAll(message, raw, redactedURL(raw))
	parsed, err := stdurl.Parse(raw)
	if err == nil {
		if parsed.User != nil {
			if password, ok := parsed.User.Password(); ok {
				message = strings.ReplaceAll(message, password, "[redacted]")
				message = strings.ReplaceAll(message, stdurl.QueryEscape(password), "[redacted]")
			}
		}
		for key, values := range parsed.Query() {
			if isSecretKey(key) {
				for _, secret := range values {
					message = strings.ReplaceAll(message, secret, "[redacted]")
				}
			}
		}
	}
	return message
}

func redactDatabaseError(err error, databaseConfig config.DatabaseConfig) error {
	message := err.Error()
	secrets := []string{databaseConfig.Password}
	if databaseConfig.URL != "" {
		message = redactURLText(message, databaseConfig.URL)
		if parsed, parseErr := stdurl.Parse(databaseConfig.URL); parseErr == nil {
			if parsed.User != nil {
				if password, ok := parsed.User.Password(); ok {
					secrets = append(secrets, password, stdurl.QueryEscape(password))
				}
			}
			for key, values := range parsed.Query() {
				if isSecretKey(key) {
					secrets = append(secrets, values...)
				}
			}
		}
	}
	sort.Slice(secrets, func(i, j int) bool { return len(secrets[i]) > len(secrets[j]) })
	for _, secret := range secrets {
		if secret != "" {
			message = strings.ReplaceAll(message, secret, "[redacted]")
		}
	}
	return fmt.Errorf("%s", message)
}

func isSecretKey(key string) bool {
	switch strings.ToLower(key) {
	case "password", "pass", "pwd":
		return true
	default:
		return false
	}
}
